councilSaints.push({"id": "nil-sorskij", "slug": "nil-sorskij", "name": "Нил Сорский", "aliases": ["Преподобный Нил Сорский"], "rank": "преподобный", "sourceId": "kirillov-nil-sorskij", "sourceLocator": "Книга 7, PDF 429: упоминание преподобного Нила Сорского среди русских иноков, посещавших Афон. Личность и почитание сверены с биографией Кирилло-Белозерского монастыря: подвижник 1433-1508 годов, связанный с Кирилловым монастырём и скитом на реке Сорке. Не Нил Столобенский и не Нил Постник. Связь со страницей является упоминанием, а не отдельным житием в этом томе."});

