councilSaints.push({"id": "patamion-akragantijskij", "slug": "patamion-akragantijskij", "name": "Патамион Акрагантийский", "aliases": ["Потамион Агригентский", "Потамий Агригентский", "Potamione di Agrigento", "Potamio di Agrigento"], "rank": "святитель, епископ", "sourceId": "santiebeati-potamione-agrigento", "sourceLocator": "Книга 3 PDF 587: крещение и воспитание Григория, переданного архидиакону Донату; PDF 592: приём аввы Марка и его спутников; PDF 596: предшественник епископа Феодора. Итальянская биография подтверждает то же лицо и местное почитание. Память 29 января приведена как сведение о местном календаре Агригента, без назначения даты в русском или старообрядческом месяцеслове."});

