councilSaints.push({"id": "isaak-presviter-uchenik-makarija", "slug": "isaak-presviter-uchenik-makarija", "name": "Исаак, пресвитер и ученик Макария", "aliases": ["Исаак, ученик Макария Египетского"], "rank": "преподобный, пресвитер", "sourceId": "local-rostov", "sourceLocator": "Книга 3, житие Иоанна Златоуста, PDF 327, печатная с. 325. Исаак прямо назван среди святых черноризцев: пресвитер, знаток Писания, ученик Макария; примечание уточняет, что учитель - Макарий Египетский. В пустыню принесён пятилетним. Свидетельство ограничено данным изданием; отдельная дата памяти и признание современной церковной традицией не установлены. Не отождествлён с другими Исааками каталога."});

councilSources.push({"id": "encyclopedia-anastasius-i-jerusalem", "title": "Анастасий I, патриарх Иерусалимский", "publisher": "Православная энциклопедия", "url": "https://pravenc.ru/text/114854.html", "kind": "article", "accessedAt": "2026-11-06", "rights": "Права на полный текст не установлены. Приведена библиографическая ссылка.", "note": "М. В. Грацианский, том 2, с. 242-243, публикация 20 августа 2008 года. Основание идентификации и отличия от одноимённых патриархов Антиохии."},{"id": "encyclopedia-juvenal-anastasius-memory", "title": "Иувеналий: почитание и совместная память с Анастасием I", "publisher": "Православная энциклопедия", "url": "https://pravenc.ru/text/1237733.html", "kind": "article", "accessedAt": "2026-11-06", "rights": "Права на полный текст не установлены. Приведена библиографическая ссылка.", "note": "И. Н. Попов, том 28, с. 358-362, публикация 21 июня 2013 года. Раздел «Почитание» описывает память Иувеналия вместе с Анастасием I под 1 июля в древних грузинских лекционариях. Современная русская память Иувеналия не переносится на Анастасия."});
councilSaints.push({"id": "anastasij-i-ierusalimskij", "slug": "anastasij-i-ierusalimskij", "name": "Анастасий I Иерусалимский", "aliases": ["Анастасий, патриарх Иерусалимский"], "rank": "святитель, патриарх", "sourceId": "encyclopedia-juvenal-anastasius-memory", "sourceLocator": "Книга 4, PDF 128, печатная с. 126: предшественник Мартирия в житии Саввы. Дополнительные места: книга 1 PDF 633 прямо называет Анастасия святым; книга 4 PDF 126 указывает годы патриаршества; книга 5 PDF 602-603 описывает его прежнее служение сосудохранителем и предсказание Евфимия Великого. Личность сверена со статьёй «Анастасий I» Православной энциклопедии (114854). Свидетельство почитания: раздел «Почитание» статьи «Иувеналий» (1237733), древние грузинские лекционарии с совместной памятью 1 июля. Эта историческая дата не назначена русской или старообрядческой традиции. Не тождествен Анастасию Синаиту, патриарху Антиохийскому."});

councilSources.push({"id": "oca-theosebia-deaconess", "title": "Blessed Theosebia the Deaconess", "publisher": "Orthodox Church in America", "url": "https://www.oca.org/saints/lives/1997/01/10/100145-blessed-theosebia-the-deaconess-sister-of-saints-basil-the-great", "kind": "calendar", "accessedAt": "2026-11-06", "rights": "Права на полный текст не установлены. Приведена библиографическая ссылка.", "note": "Календарная статья OCA подтверждает почитание диаконисы и указывает 10 января. Дата и церковная традиция OCA не перенесены автоматически в русский или старообрядческий месяцеслов."});
councilSaints.push({"id": "feosevija-feozva-diakonisa", "slug": "feosevija-feozva-diakonisa", "name": "Феосевия (Феозва), диакониса", "aliases": ["Феозва диакониса", "Феосевия диакониса", "Theosebia the Deaconess"], "rank": "блаженная, диакониса", "sourceId": "oca-theosebia-deaconess", "sourceLocator": "Книга 5, PDF 267, печатная с. 265, житие Григория Нисского. В данном издании и календарной статье OCA названа его сестрой и помощницей в церковном служении. Не тождественна жене Филарета Милостивого. Календарная дата OCA 10 января сохранена как сведение источника, без назначения другой церковной традиции."},{"id": "feozva-supruga-filareta", "slug": "feozva-supruga-filareta", "name": "Феозва, супруга Филарета", "aliases": ["Феозва, жена Филарета Милостивого"], "rank": "блаженная", "sourceId": "local-rostov", "sourceLocator": "Книга 4, PDF 10, 18-20, 22-23 и 35. На PDF 35, печатная с. 33, прямо названа блаженной; описаны её храмостроительство, помощь странникам и нищим, погребение рядом с Филаретом. Рассказ завершается обращением к молитвам обоих супругов. Карточка передаёт свидетельство этого издания; отдельная дата памяти и современная церковная традиция не установлены. Не тождественна Феозве диаконисе из жития Григория Нисского."});

