councilSources.push({"id": "catholic-adelphius-confessor", "title": "St. Adelphius the Confessor", "publisher": "Catholic Online", "url": "https://www.catholic.org/saints/saint.php?saint_id=6091", "kind": "article", "accessedAt": "2026-11-06", "rights": "Права на публикацию данной веб-редакции не установлены. Приведена ссылка на источник.", "note": "Справочная статья прямо называет Аделфия святым исповедником, связанным с Афанасием и изгнанным арианами в Фиваиду. Краткая английская формулировка о кафедре двусмысленна, кафедра подтверждена отдельно подписями Tomus ad Antiochenos. Не официальный акт канонизации."});

councilSaints.push({"id": "adelfij-onufisskij-ispovednik", "slug": "adelfij-onufisskij-ispovednik", "name": "Аделфий, епископ Онуфиса", "aliases": ["Адельфий Онуфисский", "Adelphius of Onuphis"], "rank": "исповедник", "sourceId": "catholic-adelphius-confessor", "sourceLocator": "Книга 5, PDF 528: изгнанный египетский епископ, упомянутый между Драконтием и Афинодором. Перечень совпадает с Apologia de Fuga Афанасия, § 7. В Tomus ad Antiochenos указана кафедра Onuphis, в послании 60 сан епископа и исповедника; Catholic Online прямо называет его святым. Отличается от епископа Кукуза, принявшего Иоанна Златоуста (книга 3, PDF 345, 351-352). Конкретная современная традиция и день памяти пока не назначены."});

councilSources.push({"id": "tatmitropolia-adam-eve", "title": "Великие святые твоего рода", "publisher": "Татарстанская митрополия", "url": "https://tatmitropolia.ru/all_publications/publication/default.asp?id=46261", "kind": "article", "accessedAt": "2026-11-06", "rights": "Права на публикацию не установлены. Приведена ссылка на статью.", "note": "Наталья Павлова; дата публикации на сайте 3 января 2015 года. Прямое свидетельство почитания Адама и Евы в Неделю святых праотец. Дата публикации и слово «сегодня» не используются как ежегодная дата памяти. Авторские размышления о жизни прародителей не выдаются за независимые исторические данные."});

councilSaints.push({"id": "eva-pramater", "slug": "eva-pramater", "name": "Ева, праматерь", "aliases": ["Ева"], "rank": "праведная", "sourceId": "tatmitropolia-adam-eve", "sourceLocator": "Библейская праматерь, упоминаемая в житиях, богословских поучениях и песнопениях книг Ростовского и сборника об Иоанне Шанхайском. Свидетельство почитания: публикация Татарстанской митрополии о Неделе праотцев. Упоминания не называются самостоятельным полным житием. В книге 8, PDF 453 (печатная страница 451), Ева сопоставлена с мироносицами в цитате Григория Богослова. Это богословский образ, а не рассказ о личном присутствии праматери у гроба Христа."});
councilVenerations.push({"saintId": "eva-pramater", "traditionId": "russian-orthodox", "sourceId": "tatmitropolia-adam-eve", "note": "Прямое свидетельство публикации Татарстанской митрополии. Не переносится автоматически на другие традиции."});
