councilSaints.push({"id": "adam-praotec", "slug": "adam-praotec", "name": "Адам, праотец", "aliases": ["Адам первозданный"], "rank": "праведный", "sourceId": "tatmitropolia-adam-eve", "sourceLocator": "Библейский праотец, супруг Евы. Свидетельство почитания: публикация Татарстанской митрополии о Неделе праотцев. Не преподобномученик Адам Раифский. Выражение «новый Адам» о Христе не связывается с этой персоной. Проверены страницы с упоминаниями Евы и отдельный проход по цельным формам имени Адама. Переносы, другие формы и заголовки прописными буквами этим проходом не покрыты."});
