councilSources.push({"id": "tatmitropolia-ermogen-patriarch", "title": "Священномученик Ермоген, патриарх Московский и всея Руси (+1612)", "publisher": "Татарстанская митрополия", "url": "https://www.tatmitropolia.ru/eparhia/arhipastyri_kazanskie/?ID=60715", "kind": "article", "accessedAt": "2026-11-06", "rights": "Права на публикацию не установлены. Приведена ссылка на статью.", "note": "Автор: Евгений Липаков. Имена Ермоген и Гермоген относятся к одному Казанскому митрополиту, затем Московскому патриарху. Версии происхождения и мирского имени не принимаются здесь как установленные факты. Дата 17 февраля 1612 года в заголовке относится к кончине, не к публикации сайта."});

councilSources.push({"id": "moseparh-ermogen-memories", "title": "Храм священномученика Ермогена в Южном Тушине: престольные праздники", "publisher": "Московская (городская) епархия", "url": "https://sprav.moseparh.ru/org/941", "kind": "directory", "accessedAt": "2026-11-06", "rights": "Права на публикацию не установлены. Приведена ссылка на справочник.", "note": "Раздел «Престольный праздник» прямо указывает 17 февраля и 12 мая по старому стилю. Сохраняются юлианские даты памяти; возможные переносы богослужений в конкретном году отдельно не моделируются."});

councilSaints.push({"id": "ermogen-moskovskij-patriarh", "slug": "ermogen-moskovskij-patriarh", "name": "Ермоген, патриарх Московский", "aliases": ["Гермоген", "Гермоген Московский", "Ермоген Казанский"], "rank": "священномученик", "sourceId": "tatmitropolia-ermogen-patriarch", "sourceLocator": "Казанский митрополит, затем Московский патриарх (1606-1612). В книгах Ростовского имя написано «Гермоген»: книга 1, PDF 565; книга 2, PDF 94; книга 5, PDF 380; книга 6, PDF 36 и 39. Это связанные упоминания, а не самостоятельное полное житие. Не игумен Борисоглебского монастыря из книги 5, PDF 372-373, и не полководец императора Констанция из книги 3, PDF 107."});
