councilSaints.push({"id": "elena-mat-stefana-urosha", "slug": "elena-mat-stefana-urosha", "name": "Елена, мать Стефана Уроша V", "aliases": ["Елена, супруга Стефана Душана", "Елисавета, мать Уроша", "Евгения, мать Уроша", "Јелена, мајка цара Уроша"], "rank": "святая, царица, монахиня", "sourceId": "kotor-uros-jelena", "sourceLocator": "Книга 4, PDF 45-47: супруга Душана и мать Стефана Уроша. Сербский церковный источник подтверждает почитание и имена в монашестве: Елисавета, в великой схиме Евгения. Не Елена, мать Константина. Книжные страницы являются упоминаниями в житии сына, не отдельным полным житием Елены. Ежегодная календарная дата здесь не установлена."});
