councilSaints.push({"id": "nikodim-svjatogorec", "slug": "nikodim-svjatogorec", "name": "Никодим Святогорец", "aliases": ["Никодим Агиорит", "Никодим, автор Синаксаря"], "rank": "преподобный", "sourceId": "antioch-nicodemus-hagiorite", "sourceLocator": "Книга 4, PDF 490: автор греческого Синаксаря в примечании об Аглаиде. Статья Антиохийского патриархата подтверждает агиографические труды Никодима Святогорца XVIII-XIX веков. Это библиографическое упоминание, не полное житие и не наставник Григория Паламы."});
