councilSources.push({"id": "encyclopedia-evander", "title": "Евандр", "publisher": "Православная энциклопедия", "url": "https://pravenc.ru/text/186885.html", "kind": "article", "accessedAt": "2026-11-06", "rights": "Права на публикацию не установлены. Приведены ссылка и краткие сведения.", "note": "Том 17, с. 44; публикация от 21 января 2013 года, подпись автора: Э. П. А. Святой без установленного дня памяти. Статья связывает храм, основанный Петром патрикием, с перенесением мощей Лазаря иконописца; житие Евандра не сохранилось, время жизни неизвестно."});
